@Test
public void test_parseMetadataFile_success() {
    String metadataFileContent = "[default]\n" + "version = x.y.z.0\n" + "\n" + "[kvm-x86_64]\n" + "templatename = systemvm-kvm-x.y.z\n" + "checksum = abc1\n" + "downloadurl = https://download.cloudstack.org/systemvm/x.y/systemvmtemplate-x.y.z-kvm.qcow2.bz2\n" + "filename = systemvmtemplate-x.y.z-kvm.qcow2.bz2\n" + "\n" + "[kvm-aarch64]\n" + "templatename = systemvm-kvm-x.y.z\n" + "checksum = abc2\n" + "downloadurl = https://download.cloudstack.org/systemvm/x.y/systemvmtemplate-x.y.z-kvm.qcow2.bz2\n" + "filename = systemvmtemplate-x.y.z-kvm.qcow2.bz2\n" + "\n" + "[vmware]\n" + "templatename = systemvm-vmware-x.y.z\n" + "checksum = abc3\n" + "downloadurl = https://download.cloudstack.org/systemvm/x.y/systemvmtemplate-x.y.z-vmware.ova\n" + "filename = systemvmtemplate-x.y.z-vmware.ova\n";
    try (MockedStatic<SystemVmTemplateRegistration> mockedStatic = Mockito.mockStatic(SystemVmTemplateRegistration.class, Mockito.CALLS_REAL_METHODS)) {
        setupMetadataFile(mockedStatic, metadataFileContent);
        String version = SystemVmTemplateRegistration.parseMetadataFile();
        assertEquals("x.y.z.0", version);
    }
    assertNull(SystemVmTemplateRegistration.NewTemplateMap.get("xenserver"));
    SystemVmTemplateRegistration.MetadataTemplateDetails templateDetails = SystemVmTemplateRegistration.NewTemplateMap.get("kvm-x86_64");
    assertNotNull(templateDetails);
    assertEquals(CPU.CPUArch.amd64, templateDetails.getArch());
    assertEquals(Hypervisor.HypervisorType.KVM, templateDetails.getHypervisorType());
    templateDetails = SystemVmTemplateRegistration.NewTemplateMap.get("kvm-aarch64");
    assertNotNull(templateDetails);
    assertEquals(CPU.CPUArch.arm64, templateDetails.getArch());
    assertEquals(Hypervisor.HypervisorType.KVM, templateDetails.getHypervisorType());
    templateDetails = SystemVmTemplateRegistration.NewTemplateMap.get("vmware");
    assertNotNull(templateDetails);
    assertNull(templateDetails.getArch());
    assertEquals(Hypervisor.HypervisorType.VMware, templateDetails.getHypervisorType());
}

