@Test
public void canDoReasonableNumberOfApiAccessPerSecond() throws Exception {
    int allowedRequests = 200;
    s_limitService.setMaxAllowed(allowedRequests);
    s_limitService.setTimeToLive(5);
    long startTime = System.nanoTime();
    User key = createFakeUser();
    for (int i = 0; i < allowedRequests; i++) {
        assertTrue(String.format("We should allow %d requests per second, but failed at request %d.", allowedRequests, i), isUnderLimit(key));
    }
    // we cannot really say more about this test
    boolean underLimit = isUnderLimit(key);
    long endTime = System.nanoTime();
    System.out.println("time elapsed " + (endTime - startTime) / 1000 / 1000 + " ms");
    int issued = s_limitService.getIssued(key.getAccountId());
    int timeToLive = s_limitService.getTimeToLive();
    // this assertion is really invalid as we don´t know if we exceeded the time to live for the amount of api calls (for sure)
    // so only fail if timeToLive is not exeeded and we didn´t get the requested number of calls
    assertFalse(String.format("We should block >%d requests per %d seconds (managed %d, time elapsed %d ns)", s_limitService.getMaxAllowed(), timeToLive, issued, endTime - startTime), ((endTime - startTime) / 1000000000 < timeToLive) && underLimit);
}

@Test
public void multipleClientsCanAccessWithoutBlocking() throws Exception {
    int allowedRequests = 200;
    s_limitService.setMaxAllowed(allowedRequests);
    s_limitService.setTimeToLive(1);
    final User key = createFakeUser();
    int clientCount = allowedRequests;
    Runnable[] clients = new Runnable[clientCount];
    final boolean[] isUsable = new boolean[clientCount];
    final CountDownLatch startGate = new CountDownLatch(1);
    final CountDownLatch endGate = new CountDownLatch(clientCount);
    for (int i = 0; i < isUsable.length; ++i) {
        final int j = i;
        clients[j] = new Runnable() {

            /**
             * {@inheritDoc}
             */
            @Override
            public void run() {
                try {
                    startGate.await();
                    isUsable[j] = isUnderLimit(key);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                } finally {
                    endGate.countDown();
                }
            }
        };
    }
    ExecutorService executor = Executors.newFixedThreadPool(clientCount);
    for (Runnable runnable : clients) {
        executor.execute(runnable);
    }
    startGate.countDown();
    endGate.await();
    for (boolean b : isUsable) {
        assertTrue("Concurrent client request should be allowed within limit", b);
    }
}

