}

@Test
public void testReplaceStorageXmlDiskNotManagedStorage() throws ParserConfigurationException, TransformerException, SAXException, IOException {
    final LibvirtMigrateCommandWrapper lw = new LibvirtMigrateCommandWrapper();
    String destDisk1FileName = "XXXXXXXXXXXXXX";
    String destDisk2FileName = "YYYYYYYYYYYYYY";
    String destDisk1Path = String.format("/mnt/%s/%s", destPoolUuid, destDisk1FileName);
    MigrateCommand.MigrateDiskInfo migrateDisk1Info = new MigrateCommand.MigrateDiskInfo(disk1SourceFilename, MigrateCommand.MigrateDiskInfo.DiskType.FILE, MigrateCommand.MigrateDiskInfo.DriverType.QCOW2, MigrateCommand.MigrateDiskInfo.Source.FILE, destDisk1Path);
    String destDisk2Path = String.format("/mnt/%s/%s", destPoolUuid, destDisk2FileName);
    MigrateCommand.MigrateDiskInfo migrateDisk2Info = new MigrateCommand.MigrateDiskInfo(disk2SourceFilename, MigrateCommand.MigrateDiskInfo.DiskType.FILE, MigrateCommand.MigrateDiskInfo.DriverType.QCOW2, MigrateCommand.MigrateDiskInfo.Source.FILE, destDisk2Path);
