    Map<String, UserTwoFactorAuthenticator> userTwoFactorAuthenticationProvidersMap = Mockito.mock(HashMap.class);
    Mockito.when(userTwoFactorAuthenticationProvidersMap.containsKey("staticpin")).thenReturn(true);
