        Mockito.verify(resourceLimitMgr, times(1)).checkResourceLimitWithTag(account, Resource.ResourceType.primary_storage, "tag1", vol1.getSize() + vol5.getSize());
        Mockito.verify(resourceLimitMgr, times(1)).checkResourceLimitWithTag(account, Resource.ResourceType.primary_storage, "tag2", vol1.getSize() + vol3.getSize() + vol5.getSize());
