@Test
public void validateStartDateEndDate() {
    // Valid scenario 1
    // Start date is before end date
    Date startDate = DateUtils.addDays(new Date(), 1);
    Date endDate = DateUtils.addDays(new Date(), 2);
    vmScheduleManager.validateStartDateEndDate(startDate, endDate, TimeZone.getDefault());
    // Valid Scenario 2
    // Start date is before current date and end date is null
    endDate = null;
    vmScheduleManager.validateStartDateEndDate(startDate, endDate, TimeZone.getDefault());
    // Invalid Scenario 2
    // Start date is before current date
    startDate = DateUtils.addDays(new Date(), -1);
    try {
        vmScheduleManager.validateStartDateEndDate(startDate, endDate, TimeZone.getDefault());
        Assert.fail("Should have thrown InvalidParameterValueException");
    } catch (InvalidParameterValueException e) {
        Assert.assertTrue(e.getMessage().contains("Invalid value for start date. Start date") && e.getMessage().contains("can't be before current time"));
    }
    // Invalid Scenario 2
    // Start date is after end date
    startDate = DateUtils.addDays(new Date(), 2);
    endDate = DateUtils.addDays(new Date(), 1);
    try {
        vmScheduleManager.validateStartDateEndDate(startDate, endDate, TimeZone.getDefault());
        Assert.fail("Should have thrown InvalidParameterValueException");
    } catch (InvalidParameterValueException e) {
        Assert.assertTrue(e.getMessage().contains("Invalid value for end date. End date") && e.getMessage().contains("can't be before start date"));
    }
    // Invalid Scenario 3
    // End date is before current date
    startDate = DateUtils.addDays(new Date(), 1);
    endDate = DateUtils.addDays(new Date(), -1);
    try {
        vmScheduleManager.validateStartDateEndDate(startDate, endDate, TimeZone.getDefault());
        Assert.fail("Should have thrown InvalidParameterValueException");
    } catch (InvalidParameterValueException e) {
        Assert.assertTrue(e.getMessage().contains("Invalid value for end date. End date") && e.getMessage().contains("can't be before current time"));
    }
}

