@Test
public void testMultithreadedPoolClients() throws Exception {
    vmwareContextPool = Mockito.spy(vmwareContextPool);
    final ExecutorService executor = Executors.newFixedThreadPool(10, new NamedThreadFactory("VmwareContextPoolClients"));
    final List<PoolClient> clients = new ArrayList<>();
    for (int i = 0; i < 50; i++) {
        final PoolClient client = new PoolClient(vmwareContextPool);
        clients.add(client);
        executor.submit(client);
    }
    Thread.sleep(1000);
    executor.shutdown();
    int totalRegistrations = 0;
    for (final PoolClient client : clients) {
        client.stop();
        totalRegistrations += client.count();
    }
    Mockito.verify(vmwareContextPool, Mockito.atLeast(totalRegistrations)).registerContext(Mockito.any(VmwareContext.class));
}

@Test
public void testUploadResourceContentCharsetException() throws Exception {
    VmwareClient client = Mockito.mock(VmwareClient.class);
    String address = "10.1.1.1";
    VmwareContext vmwareContext = Mockito.spy(new VmwareContext(client, address));
    HttpURLConnection conn = Mockito.mock(HttpURLConnection.class);
    Mockito.doReturn(Mockito.mock(OutputStream.class)).when(conn).getOutputStream();
    Mockito.doReturn(Mockito.mock(InputStream.class)).when(conn).getInputStream();
    Mockito.doReturn(conn).when(vmwareContext).getHTTPConnection("http://example.com", "PUT");
    //This method should not throw any exception. Ref: CLOUDSTACK-8669
    vmwareContext.uploadResourceContent("http://example.com", "content".getBytes());
    Mockito.verify(vmwareContext, Mockito.times(1)).getHTTPConnection("http://example.com", "PUT");
    Mockito.verify(conn, Mockito.times(1)).getOutputStream();
    Mockito.verify(conn, Mockito.times(1)).getInputStream();
}

